/****************************************************************************/
/* Status Bar                                                               */
/****************************************************************************/

static lv_obj_t *g_time_label;
static lv_obj_t *g_wifi_label;

static void create_status_bar(lv_obj_t *parent)
{
  lv_obj_t *bar = lv_obj_create(parent);
  lv_obj_set_size(bar, SCREEN_W, STATUS_BAR_H);
  lv_obj_set_pos(bar, 0, 0);
  lv_obj_set_style_bg_color(bar, color_hex(0x2C3E50), 0);
  lv_obj_set_style_border_width(bar, 0, 0);
  lv_obj_set_style_pad_all(bar, 2, 0);
  lv_obj_clear_flag(bar, LV_OBJ_FLAG_SCROLLABLE);

  g_time_label = lv_label_create(bar);
  lv_obj_set_style_text_color(g_time_label, color_hex(0xFFFFFF), 0);
  lv_obj_align(g_time_label, LV_ALIGN_LEFT_MID, 5, 0);
  lv_label_set_text(g_time_label, "00:00");

  lv_obj_t *name_lbl = lv_label_create(bar);
  lv_obj_set_style_text_color(name_lbl, color_hex(0xECF0F1), 0);
  lv_obj_align(name_lbl, LV_ALIGN_CENTER, 0, 0);
  lv_label_set_text(name_lbl, pet_name);

  g_wifi_label = lv_label_create(bar);
  lv_obj_set_style_text_color(g_wifi_label, color_hex(0x27AE60), 0);
  lv_obj_align(g_wifi_label, LV_ALIGN_RIGHT_MID, -5, 0);
  lv_label_set_text(g_wifi_label, "WiFi");
}

